func failure(code, category string, exit int, retryable bool, cause string) Entry {
	return Entry{Code: code, Kind: KindError, Status: Active, Category: category, Exit: exit, Retryable: retryable, Cause: cause}
}

func fallback(code, category string, exit int, cause string) Entry {
	e := failure(code, category, exit, false, cause)
	e.Unclassified = true
	return e
}

func reason(code, category string, exit int, cause string) Entry {
	return Entry{Code: code, Kind: KindReason, Status: Active, Category: category, Exit: exit, Cause: cause}
}

func notice(code, cause string) Entry {
	return Entry{Code: code, Kind: KindNotice, Status: Active, Category: "notice", Cause: cause}
}

func planned(code, category string, exit int, retryable bool, cause string) Entry {
	return Entry{Code: code, Kind: KindError, Status: Planned, Category: category, Exit: exit, Retryable: retryable, Cause: cause}
}

func retired(code, retiredIn, cause string, replacedBy ...string) Entry {
	return Entry{Code: code, Kind: KindError, Status: Retired, Cause: cause, RetiredIn: retiredIn, ReplacedBy: replacedBy}
}

